    sub1="A replay of one real run on AKS (${TITLE_DATE}): ${TITLE_STEPS} RL steps in ${TITLE_DURATION}, on one node with ${TITLE_GPUS} × H100 GPUs."
    sub2="Nothing is rerun: all output comes from the saved runs."

    beat_header "🚀" "$title" "$sub1" "$sub2"
}

# ---- beats/01_problem.sh ----
# beats/01_problem.sh: beat 01, the problem. What ReTool is and why Qwen3-4B as it ships needs SFT and
# RL for it; one real trajectory turn by turn (sample 1481: right, +1) and a wrong attempt at the same
# problem (sample 1485, −1.05); ReTool's code; the RL loop; and what runs where on the node.
# Data: build/01_problem.data.sh, from fill/01_problem.py. Every line of model text, code, sandbox
# output, and every number comes from there.
#
# Three screens, each cleared: 1. two cards and the definitions of trajectory and turn;
# 2. the transcript; 3. the code, the loop, and the node. Screens 2 and 3 fit in 32 rows.
# The transcript blocks hold for a skim (PROBLEM_SKIM_*), not their full reading time: the model's
# text is there to look at, and the narration carries the point.

# problem_hl LANG TEXT → _HL: TEXT highlighted as LANG, as one string with escapes.
problem_hl() {
    local k
    hl_line "$1" "$2"
    _HL=""
    for (( k=0; k<${#SEG_TXT[@]}; k++ )); do _HL+="${SEG_COL[k]}${SEG_TXT[k]}"; done
    _HL+="$NC"
}

# problem_row LABEL TEXT [NOTE]: one transcript row. LABEL sits in a gutter of PROBLEM_GUTTER
# columns; NOTE, if given, starts at column 56 in the dim color.
problem_row() {
    local label="$1" text="$2" note="${3:-}" left note_col=56
    padr left "$PROBLEM_GUTTER" "  ${label}${NC}"
    if [[ -n "$note" ]]; then
        padr text $(( note_col - PROBLEM_GUTTER )) "$text"
        text+="${DIM}◀ ${note}"
    fi
    printf '%s%s%s\n' "$left" "$text" "$NC"
}

# problem_box TITLE LINE...: a box like card's, CARD_W wide, but each LINE is printed as is
# (no wrapping, so columns inside it stay aligned). LINEs may hold escapes.
problem_box() {
    local title="$1" line pad ind iw=$(( CARD_W - 4 ))
    shift
    printf -v ind '%*s' "$CARD_INDENT" ''
    dwidth "$title"
    _rep '─' $(( CARD_W - 5 - _W ))
    printf '%s%s╭─ %s%s%s%s %s╮%s\n' "$ind" "$CARDB" "$NC" "$BOLD" "$title" "$CARDB" "$_REP" "$NC"
    for line in "$@"; do
        padr pad "$iw" "$line"
        printf '%s%s│%s %s%s %s│%s\n' "$ind" "$CARDB" "$NC" "$pad" "$NC" "$CARDB" "$NC"
    done
    _rep '─' $(( CARD_W - 2 ))
    printf '%s%s╰%s╯%s\n' "$ind" "$CARDB" "$_REP" "$NC"
}

# problem_title TEXT: a one-row title for screens 2 and 3, then a blank row.
problem_title() { printf '  %s%s%s\n\n' "$BOLD" "$1" "$NC"; }

# Box pieces for the node diagram: VAR WIDTH [TEXT]. The borders are dim.
problem_box_top() {
    dwidth "$3"
    _rep '─' $(( $2 - 5 - _W ))
    printf -v "$1" '%s┌─ %s%s%s %s┐%s' "$DIM" "$NC$BOLD" "$3" "$NC$DIM" "$_REP" "$NC"
}
problem_box_mid() {
    local t
    padr t $(( $2 - 4 )) "$3"
    printf -v "$1" '%s│%s %s%s %s│%s' "$DIM" "$NC" "$t" "$NC" "$DIM" "$NC"
}
problem_box_bottom() {
    _rep '─' $(( $2 - 2 ))
    printf -v "$1" '%s└%s┘%s' "$DIM" "$_REP" "$NC"
}

problem_screen_why() {
    beat_header "🧮" "$PROBLEM_TITLE"
    card "ReTool: math with a Python tool" \
        "ReTool, from a 2025 ByteDance Seed paper on RL for strategic tool use, ships as a Slime example. The model solves competition math and can stop partway to run Python, then carry on with the output in view."
    card "Why not use Qwen3-4B as it ships?" \
        "Off the shelf, ${PROBLEM_SFT_BASE} reasons in text and does the arithmetic in its head. Fine-tuning on ReTool-SFT traces (SFT) teaches it to run code mid-solution and carry on from the output: this run starts from that checkpoint, ${PROBLEM_CKPT}. RL then teaches when and how to use the tool, rewarding only the final answer."
    printf '\n'
    narrate "Next, one trajectory: one attempt at one problem from DAPO-Math-17k (${PROBLEM_N_PROBLEMS} problems, each labeled with its answer)." \
            "A turn is one model call, ending at a tool call or an answer: one request to Dynamo."
}

problem_screen_trajectory() {
    local k label text last
    clear_screen
    problem_title "🧮 One trajectory (Slime calls it a sample): sample ${PROBLEM_EX_SAMPLE}, ${PROBLEM_EX_TURNS} turns"

    for (( k=0; k<${#PROBLEM_PROMPT[@]}; k++ )); do
        label=""; text="${PROBLEM_PROMPT[k]}"
        if (( k == 0 )); then label="${BOLD}prompt"; fi
        if (( k == PROBLEM_PROBLEM_ROW )); then text="${BOLD}${text}"; fi
        problem_row "$label" "$text"
    done
    nap 2

    for (( k=0; k<${#PROBLEM_T1[@]}; k++ )); do
        label=""; if (( k == 0 )); then label="${BOLD}turn 1"; fi
        problem_row "$label" "${PROBLEM_T1[k]}"
    done
    problem_row "" "${CMD}${PROBLEM_CALL[0]}"
    problem_row "" "${DIM}${PROBLEM_CALL[1]}"
    problem_row "" "${CMD}${PROBLEM_CALL[2]}" "generation stops at the tool call"
    nap 3.5

    hl_reset python
    for (( k=0; k<${#PROBLEM_CODE[@]}; k++ )); do
        problem_hl python "${PROBLEM_CODE[k]}"
        if (( k == 0 )); then
            problem_row "${OK}sandbox" "$_HL" "ReTool runs the code in a Python subprocess"
        else
            problem_row "" "$_HL"
        fi
    done
    last=$(( ${#PROBLEM_OBS[@]} - 1 ))
    problem_row "" "${CMD}${PROBLEM_OBS[0]}" "the output is appended to the transcript,"
    for (( k=1; k<last; k++ )); do problem_row "" "${STR}${PROBLEM_OBS[k]}"; done
    problem_row "" "${CMD}${PROBLEM_OBS[last]}" "and all of it goes back to the model: turn 2"
    nap 2.5

    last=$(( ${#PROBLEM_T2[@]} - 1 ))
    for (( k=0; k<=last; k++ )); do
        label=""; if (( k == 0 )); then label="${BOLD}turn 2"; fi
        if (( k == last )); then
            problem_row "$label" "${BOLD}${PROBLEM_T2[k]}" "an answer ends the trajectory"
        else
            problem_row "$label" "${PROBLEM_T2[k]}"
        fi
    done
    nap 2
    problem_row "${BOLD}reward" "${OK}${BOLD}${PROBLEM_REWARD}${NC}  reward_func: the answer, ${PROBLEM_PRED}, matches the label, ${PROBLEM_LABEL}, which the model never saw"
    nap 2

    printf '\n'
    for (( k=0; k<${#PROBLEM_ALT[@]}; k++ )); do
        label=""; if (( k == 0 )); then label="${NUM}wrong"; fi
        problem_row "$label" "${PROBLEM_ALT[k]}"
    done
    nap 4.5
    narrate "Training makes what the ${PROBLEM_REWARD} trajectory wrote more likely, and what the ${PROBLEM_ALT_REWARD} one wrote less likely."
}

problem_screen_loop() {
    local bw=46 mg=16 i ind="  " g1 g2 g3 g4 a b l
    local -a dyn=("frontend + router" "▣ ▣ ▣ ▣  ${PROBLEM_ENGINES} SGLang engines, 1 GPU each")
    local -a sli=("generate(), reward_func(), sandbox (CPU)" "▣ ▣ ▣ ▣  Megatron-LM trainer, ${PROBLEM_TRAIN_GPUS} GPUs")
    local sig0 sig1 sig2

    clear_screen
    problem_title "🧮 ReTool's code, the RL loop, and what runs where"

    hl_reset python
    problem_hl python "${PROBLEM_SIGS[0]}"; padr sig0 70 "$_HL"
    problem_hl python "${PROBLEM_SIGS[1]}"; padr sig1 70 "$_HL"
    problem_hl python "${PROBLEM_SIGS[2]}"; padr sig2 70 "$_HL"
    problem_box "ReTool's code: generate_with_retool.py and tool_sandbox.py (Step 4 opens it)" \
        "${sig0}${NAR}# one trajectory, turn by turn" \
        "${sig1}${NAR}# +1 if right, about −1 if wrong" \
        "${sig2}${NAR}# runs the code: ${PROBLEM_SANDBOX_MEM}, ${PROBLEM_SANDBOX_SECS} s at most"
    nap 3

    printf '\n  %sThe RL loop, repeated (%s times in this run):%s\n' "$BOLD" "$PROBLEM_STEPS" "$NC"
    printf '   %s①%s rollout      Dynamo serves every turn while %sgenerate()%s makes trajectories and %sreward_func()%s scores them\n' \
        "$NUM" "$NC" "$FUNC" "$NC" "$FUNC" "$NC"
    printf '   %s②%s train        the trainer updates the weights toward the trajectories that scored higher\n' "$NUM" "$NC"
    printf '   %s③%s weight sync  the trainer writes the new weights to Lustre; each engine loads them for the next rollout\n' "$NUM" "$NC"
    nap 7

    # The node: two boxes side by side, the rollout between them, Lustre below.
    printf '\n%s%sOne AKS node · %s · %s × %s%s\n' "$ind" "$BOLD" "$PROBLEM_VM" "$PROBLEM_NODE_GPUS" "$PROBLEM_GPU_NAME" "$NC"
    padr g1 "$mg" "   ${NUM}①${NC} rollout"
    g2=" ◀─── turns ─── "
    g3=" ── replies ──▶ "
    padr g4 "$mg" ""
    problem_box_top a "$bw" "Dynamo serves the model"
    problem_box_top b "$bw" "Slime trains it, on KubeRay"
    printf '%s%s%s%s\n' "$ind" "$a" "$g1" "$b"
    for i in 0 1; do
        problem_box_mid a "$bw" "${dyn[i]}"
        problem_box_mid b "$bw" "${sli[i]}"
        if (( i == 0 )); then l=$g2; else l=$g3; fi
        printf '%s%s%s%s\n' "$ind" "$a" "$l" "$b"
    done
    problem_box_bottom a "$bw"
    printf '%s%s%s%s\n' "$ind" "$a" "$g4" "$a"
    padr a $(( bw + mg )) "      ▲ ${NUM}③${NC} each engine loads the new weights"
    printf '%s%s      │ %s③%s the trainer writes them\n' "$ind" "$a" "$NUM" "$NC"
    padr a $(( bw + mg )) "      │"
    printf '%s%s      ▼\n' "$ind" "$a"
    l=" Azure Managed Lustre: /data, with the checkpoint, the dataset, and each new version of the weights "
    dwidth "$l"
    _rep '═' $(( (2 * bw + mg - _W) / 2 )); a=$_REP
    _rep '═' $(( 2 * bw + mg - _W - (2 * bw + mg - _W) / 2 )); b=$_REP
    printf '%s%s%s%s%s%s%s%s\n' "$ind" "$DIM" "$a" "$NC$BOLD" "$l" "$NC$DIM" "$b" "$NC"
    nap 7
}

PROBLEM_TITLE="The Problem: Math with a Python Tool"

beat_01() {
    problem_screen_why
    problem_screen_trajectory
    problem_screen_loop
}

# ---- beats/02_cluster.sh ----
# beats/02_cluster.sh: beat 02, Step 1: prepare the AKS cluster.
# First the install commands a plain AKS cluster needs, emulated: this cluster already runs them all,
# the narration says so, and no output is shown for them. Then the cluster's real state, from
# read-only snapshots taken on 2026-11-19.
# Data: build/02_cluster.data.sh, from fill/02_cluster.py (snapshots and the kit's manifests). Every
# version and flag value in the commands comes from there.

CLUSTER_TITLE="Step 1: Prepare the AKS Cluster"

# cluster_type LINE...: show_command_lines for an emulated command: typed 4 characters per tick
# (4× normal speed), with shorter pauses because it doesn't run, and no output.
cluster_type() {
    local line chunk=4 prompt_pause=0.2 cmd_pause=0.3
    cursor_show
    printf '%s ' "${PROMPT}❯${NC}"
    nap "$prompt_pause"
    hl_bash_reset
    for line in "$@"; do
        seg_reset; hl_bash "$line"
        type_segments "$chunk"
        printf '\n'
    done
    cursor_hide
    nap "$cmd_pause"
}

cluster_install() {
    beat_header "🧰" "$CLUSTER_TITLE"
    narrate "What a plain AKS cluster needs first, at this cluster's versions (all installed already, so nothing runs here):"
    narrate "GPU nodes: ${CLUSTER_POOL_COUNT} × ${CLUSTER_VM_SHORT}, ${CLUSTER_GPUS_PER_NODE} × ${CLUSTER_GPU_NAME} each, without AKS's GPU driver:"
    cluster_type "${CLUSTER_CMD_NODEPOOL[@]}"
    narrate "Node Feature Discovery labels hardware; the GPU Operator installs the driver (${CLUSTER_DRIVER}) and device plugin:"
    cluster_type "${CLUSTER_CMD_NFD[@]}"
    cluster_type "${CLUSTER_CMD_NVIDIA_REPO[@]}"
    cluster_type "${CLUSTER_CMD_GPU_OP[@]}"
    narrate "KubeRay, for Ray jobs like Slime's trainer:"
    cluster_type "${CLUSTER_CMD_KUBERAY_REPO[@]}"
    cluster_type "${CLUSTER_CMD_KUBERAY[@]}"
    narrate "Dynamo's platform, plus Grove and the KAI scheduler, which place a Dynamo deployment's Pods as one group:"
    cluster_type "${CLUSTER_CMD_KAI[@]}"
    cluster_type "${CLUSTER_CMD_GROVE[@]}"
    cluster_type "${CLUSTER_CMD_DYNAMO[@]}"
    narrate_wrap "Azure Managed Lustre, the shared file system for the run: ${CLUSTER_AMLFS_TIB} TiB, ${CLUSTER_AMLFS_SKU_SHORT}, ${CLUSTER_AMLFS_MBPS} MB/s, in its own ${CLUSTER_AMLFS_SUBNET_PREFIX} subnet. Then its CSI driver:"
    cluster_type "${CLUSTER_CMD_AMLFS[@]}"
    cluster_type "${CLUSTER_CMD_CSI[@]}"
    nap "$PAUSE_SHORT"
}

cluster_state() {
    clear_screen
    step_header_bars "🧰" "$CLUSTER_TITLE"
    narrate "The cluster's state on ${CLUSTER_SNAPSHOT_DATE}, from read-only queries:"
    show_command "${CLUSTER_CMD_SHOW_HELM[0]}"
    printf '%s\n' "${CLUSTER_OUT_HELM[@]}"
    nap "$PAUSE_LONG"
    show_command "${CLUSTER_CMD_SHOW_NODES[0]}"
    printf '%s\n' "${CLUSTER_OUT_NODES[@]}"
    nap "$PAUSE_MED"
    show_command_lines "${CLUSTER_CMD_SHOW_AMLFS[@]}"
    printf '%s\n' "${CLUSTER_OUT_AMLFS[@]}"
    nap "$PAUSE_MED"
    printf '\n'
    narrate "This run uses one of these GPU nodes: ${CLUSTER_ENGINE_GPUS} GPUs for Dynamo's engines, ${CLUSTER_TRAIN_GPUS} for training."
}

beat_02() {
    cluster_install
    cluster_state
    nap "$PAUSE_MED"
}

# ---- beats/03_storage.sh ----
# beats/03_storage.sh: beat 03, Step 2: stage the model and data on Azure Managed Lustre.
# Why the run needs one shared volume and what goes on it; storage.yaml typed in vim (fast),
# pausing at ReadWriteMany and Retain, at the Lustre CSI block, and at the static PV-claim
# binding; then one narrated command at a time: create the storage, create the setup Job, wait
# for it (its 109 s fast-forwarded on the real phase times), and list the volume from its log.
# Data: build/03_storage.data.sh, from fill/03_storage.py. Plan: plans/03-04_storage_serve.md.

# storage_setup_render T: one frame of the setup Job's fast-forward (T: seconds since the Job
# started). Phases from setup.log: downloads done at STORAGE_DL_T, the torch_dist copy saved at
# STORAGE_CONV_T, then the folders and the listing until the Job completes.
storage_setup_render() {
    local t="$1"
    if (( t < STORAGE_DL_T )); then
        fl "   ${STATUS}▸ Downloading ${STORAGE_MODEL} and ${STORAGE_DATASET} from Hugging Face...${NC}"
    else
        fl "   ${OK}✓${NC} Downloaded the checkpoint and the dataset ${DIM}(${STORAGE_DL_SECS} s)${NC}"
        if (( t < STORAGE_CONV_T )); then
            fl "   ${STATUS}▸ Converting the checkpoint to torch_dist on 1 GPU...${NC}"
        else
            fl "   ${OK}✓${NC} Converted the checkpoint to torch_dist ${DIM}(${STORAGE_CONV_SECS} s)${NC}"
            fl "   ${STATUS}▸ Creating /data/weight-updates and /data/turn-logs...${NC}"
        fi
    fi
    ff_elapsed "$t"
}

# storage_vim: "write" storage.yaml, fast, with a callout after each interesting part.
storage_vim() {
    local -a L=("${STORAGE_YAML[@]}")
    local retain=$STORAGE_LN_RETAIN subdir=$STORAGE_LN_SUBDIR volname=$STORAGE_LN_VOLNAME
    narrate "Write the manifests: a PersistentVolume (PV) for the Lustre folder, and the claim (PVC) that Pods mount:"
    vim_open "$STORAGE_FILE"
    vim_type fast "${L[@]:0:retain}"
    vim_callout "$STORAGE_LN_ACCESS" "$retain" \
        "${BOLD}ReadWriteMany${NC}: Pods on any node can mount it read-write at once. ${BOLD}Retain${NC}: deleting the PV keeps the files."
    vim_type fast "${L[@]:retain:subdir-retain}"
    vim_callout "$STORAGE_LN_CSI" "$subdir" \
        "The ${BOLD}Azure Lustre CSI driver${NC} from Step 1 mounts the file system into the run's own folder," \
        "${BOLD}sub-dir${NC} slime-retool/, which it creates on first mount."
    vim_type fast "${L[@]:subdir:volname-subdir}"
    vim_callout "$STORAGE_LN_CLAIMREF" "$volname" \
        "A ${BOLD}static PV${NC}: no storage class here creates Lustre volumes on demand, so the PV and the claim name each other" \
        "(claimRef, volumeName)."
    vim_type fast "${L[@]:volname}"
    vim_close
}

# storage_commands: create the storage and the setup Job, wait for it, and check the volume.
storage_commands() {
    printf '\n'
    narrate "Create the namespace, the PV, and the claim:"
    show_command "kubectl apply -f ${STORAGE_FILE}"
    printf '%s\n' "${STORAGE_APPLY_OUT[@]}"
    nap "$PAUSE_SHORT"
    show_command "export NAMESPACE=${STORAGE_NAMESPACE}"
    printf '\n'
    narrate "A one-time Job on 1 GPU downloads the checkpoint and dataset, then converts it to the trainer's format, torch_dist:"
    show_command 'kubectl apply -n $NAMESPACE -f manifests/setup-job.yaml'
    printf '%s\n' "$STORAGE_JOB_CREATED_OUT"
    nap "$PAUSE_SHORT"
    printf '\n'
    narrate "Wait for it to finish, fast-forwarding its ${STORAGE_JOB_SECS} s:"
    show_command "kubectl wait -n \$NAMESPACE --for=condition=complete job/${STORAGE_JOB} --timeout=30m"
    ff_run storage_setup_render 0 "$STORAGE_JOB_SECS"
    nap "$PAUSE_SHORT"
    frame_replace "$STORAGE_JOB_MET_OUT"
    nap "$PAUSE_SHORT"
    printf '\n'
    narrate "Its log ends by listing what's on the volume:"
    show_command "kubectl logs -n \$NAMESPACE job/${STORAGE_JOB} --tail=${STORAGE_TAIL_N}"
    printf '%s\n' "${STORAGE_TAIL_OUT[@]}"
    nap 3
}

beat_03() {
    local title="Step 2: Stage the Model and Data on Azure Managed Lustre"
    beat_header "📦" "$title" \
        "Every Pod in the run shares one folder, /data: the setup Job, the 4 engines, and the trainer." \
        "It holds the checkpoint, a copy in the trainer's format, the ${STORAGE_PROBLEMS} problems, and each step's new weights."
    storage_vim
    storage_commands
}

# ---- beats/04_serve.sh ----
# beats/04_serve.sh: beat 04, Step 3: serve an inference endpoint with Dynamo.
# The DGD typed in vim: its header at normal speed, fast-forwarded to the engine's image and
# command, a callout before the frontend's router settings and another before the engine's KV
# flags, worker-1..3 folded. Then why four components, where the engine Services come from (the
# head of engine-services.yaml), the apply, the Pods starting (fast-forwarded on the recorded
# transitions), the DGD Ready, and each sidecar's KV-event line, explained before it runs.
# Data: build/04_serve.data.sh, from fill/04_serve.py. Plan: plans/03-04_storage_serve.md.

# serve_type MODE A B: type dgd.yaml's buffer lines A..B (1-based, inclusive) at MODE speed.
# A flag and its value marked in SERVE_HIDE (--host 0.0.0.0, the sidecar's 127.0.0.1 endpoint) go
# in as a closed fold instead, so tools/redact_cast.py finds no address to flag in the public cast.
serve_type() {
    local mode="$1" a="$2" b="$3" i j k
    i=$a
    while (( i <= b )); do
        k=${SERVE_HIDE[i-1]}
        j=$i
        if (( k > 0 )); then
            while (( j < b )) && (( ${SERVE_HIDE[j]} == k )); do j=$(( j + 1 )); done
            vim_fold_in "${SERVE_HIDE_NOTE[k-1]}" "${SERVE_DGD[@]:i-1:j-i+1}"
        else
            while (( j < b )) && (( ${SERVE_HIDE[j]} == 0 )); do j=$(( j + 1 )); done
            vim_type "$mode" "${SERVE_DGD[@]:i-1:j-i+1}"
        fi
        i=$(( j + 1 ))
    done
    return 0
}

# serve_pods_render T: one frame of `watch kubectl get pods` (T: seconds since the apply). Each
# Pod's STATUS and READY follow the transitions recorded in runs/deploy/pods-watch.txt, AGE counts
# from its creationTimestamp, and each column is as wide as its widest value + 3 in this frame,
# the way kubectl pads it.
serve_pods_render() {
    local t="$1" i j n=0 np=${#SERVE_POD_NAMES[@]} wn=4 ws=6 fmt line
    local -a st=() rd=()
    for (( i=0; i<np; i++ )); do st[i]=""; rd[i]=""; done
    for (( j=0; j<${#SERVE_TR_T[@]}; j++ )); do
        if (( ${SERVE_TR_T[j]} <= t )); then
            st[${SERVE_TR_I[j]}]=${SERVE_TR_S[j]}
            rd[${SERVE_TR_I[j]}]=${SERVE_TR_R[j]}
        fi
    done
    for (( i=0; i<np; i++ )); do
        if (( ${#SERVE_POD_NAMES[i]} > wn )); then wn=${#SERVE_POD_NAMES[i]}; fi
        if (( ${#st[i]} > ws )); then ws=${#st[i]}; fi
        if [[ "${rd[i]}" == "1/1" ]]; then n=$(( n + 1 )); fi
    done
    fmt="%-$(( wn + 3 ))s%-8s%-$(( ws + 3 ))s%-11s%s"
    printf -v line "$fmt" NAME READY STATUS RESTARTS AGE
    fl "$line"
    for (( i=0; i<np; i++ )); do
        fmt_age $(( t - ${SERVE_POD_CREATED_T[i]} ))
        printf -v line "$fmt" "${SERVE_POD_NAMES[i]}" "${rd[i]}" "${st[i]}" 0 "$AGE_STR"
        fl "$line"
    done
    fl ""
    if (( n == np )); then
        fl "   ${OK}✅ All ${np} Pods ready: all four engines can generate${NC}"
    elif [[ "${st[0]}" == SchedulingGated ]]; then
        fl "   ${STATUS}▸ SchedulingGated: the ${np} Pods wait to be placed as one group (Step 1's Grove and KAI)${NC} — ${n}/${np} ready"
        FF_TICK_NOW=$SERVE_GATED_TICK
    else
        fl "   ${STATUS}▸ Starting the frontend and four engines (Qwen3-4B from /data, CUDA graphs)${NC} — ${n}/${np} ready"
    fi
    fl ""
    ff_elapsed "$t"
}

SERVE_GATED_TICK="${SERVE_GATED_TICK:-0.6}"   # per frame while the Pods are SchedulingGated

# serve_vim_dgd: "write" dgd.yaml.
serve_vim_dgd() {
    narrate "Write the DynamoGraphDeployment (DGD) that runs them:"
    vim_open "$SERVE_DGD_FILE"
    serve_type normal 1 $(( SERVE_LN_FRONTEND - 1 ))
    serve_type fast "$SERVE_LN_FRONTEND" $(( SERVE_LN_W0 - 1 ))
    vim_callout "$SERVE_LN_ENV" $(( SERVE_LN_W0 - 1 )) \
        "The ${BOLD}frontend${NC}, Dynamo's HTTP entry point and router:" \
        "DYN_SGLANG_ENABLE_GENERATE=1: serve SGLang's /generate (token IDs in and out), which Slime calls." \
        "DYN_ROUTER_MODE=kv: ${BOLD}KV-aware routing${NC}, to the engine that already processed most of the prompt, unless it's busier." \
        "DYN_ROUTER_PREDICTED_TTL_SECS=5: for 5 s after routing, assume that engine has the prompt."
    serve_type fast "$SERVE_LN_W0" $(( SERVE_LN_W0_IMAGE - 1 ))
    serve_type normal "$SERVE_LN_W0_IMAGE" "$SERVE_LN_W0_LAUNCH"
    vim_callout "$SERVE_LN_W0_IMAGE" "$SERVE_LN_W0_LAUNCH" \
        "Each ${BOLD}engine${NC} is SGLang's own server, started from Dynamo's SGLang image."
    serve_type fast $(( SERVE_LN_W0_LAUNCH + 1 )) "$SERVE_LN_W0_SIDECAR_ARGS"
    vim_callout "$SERVE_LN_W0_PAGE" "$SERVE_LN_W0_SIDECAR_ARGS" \
        "--page-size 16: keep the ${BOLD}KV cache${NC}, the engine's saved work on past prompts, in 16-token blocks, the router's unit." \
        "--kv-events-config: announce each block the engine stores or drops, on a ZMQ socket." \
        "--sidecar: ${BOLD}Dynamo's sidecar${NC} passes the engine its requests and relays those announcements to the router."
    serve_type fast $(( SERVE_LN_W0_SIDECAR_ARGS + 1 )) $(( SERVE_LN_W1 - 1 ))
    vim_collapse_begin "worker-1..3: same as worker-0, except the name and label"
    serve_type collapse "$SERVE_LN_W1" "${#SERVE_DGD[@]}"
    vim_collapse_end
    vim_close
}

# serve_services: why four components, and the engine Services the apply creates.
serve_services() {
    printf '\n'
    narrate "Why four components, not one with replicas: 4? Each engine needs its own label, so a Service can reach just it:"
    show_command "head -n ${SERVE_SVC_HEAD_N} ${SERVE_SVC_FILE}"
    printf '%s\n' "${SERVE_SVC_HEAD_OUT[@]}"
    nap 3
}

# serve_deploy TITLE: apply, watch the Pods start, check the DGD and the sidecars.
serve_deploy() {
    local title="$1"
    local cmd='watch kubectl get pods -n $NAMESPACE -l dynamo.nvidia.com/slime-role'
    local n1="Fast-forwarding while the Pods start and the engines load the model from /data:"
    printf '\n'
    narrate "Create the four engine Services and the DGD:"
    show_command 'kubectl apply -n $NAMESPACE -f manifests/engine-services.yaml -f manifests/dgd.yaml'
    printf '%s\n' "${SERVE_APPLY_OUT[@]}"
    nap "$PAUSE_SHORT"
    printf '\n'
    narrate "$n1"
    show_command "$cmd"

    clear_screen
    step_header_bars "🚀" "$title"
    printf '%s\n\n' "${NAR}# ${n1}${NC}"
    print_command "$cmd"
    printf '\n'
    ff_run serve_pods_render "$SERVE_WATCH_FROM_T" "$SERVE_WATCH_TO_T"
    nap "$PAUSE_MED"

    printf '\n'
    narrate "The DGD reports Ready once all five Pods are:"
    show_command "kubectl get dgd -n \$NAMESPACE ${SERVE_DGD_NAME}"
    printf "${DGD_FMT}\n" NAME READY BACKEND AGE
    printf "${DGD_FMT}\n" "$SERVE_DGD_NAME" "$SERVE_DGD_READY" "$SERVE_DGD_BACKEND" "$SERVE_DGD_AGE"
    nap "$PAUSE_SHORT"
    printf '\n'
    narrate "Last check: each engine's sidecar should have found its engine's KV-event stream (the ZMQ socket set above)." \
            "Through it, the router learns what each engine has cached:"
    show_command_lines \
        "for w in 0 1 2 3; do kubectl logs -n \$NAMESPACE -l dynamo.nvidia.com/slime-role=worker-\$w --tail=-1 \\" \
        "    | grep -o 'discovered SGLang ZMQ KV-event sources.*' | sed \"s/^/worker-\$w: /\"; done"
    printf '%s\n' "${SERVE_SIDECAR_OUT[@]}"
    nap 2.5
    printf '\n'
    narrate "The endpoint is up: the frontend's Service, which the operator created, at ${SERVE_FRONTEND_URL}."
}

beat_04() {
    local title="Step 3: Serve an Inference Endpoint with Dynamo"
    beat_header "🚀" "$title" \
        "The loop starts by serving the starting checkpoint as is: Qwen3-4B after ReTool SFT, before any RL step." \
        "Dynamo serves it instead of Slime's own engines: a KV-aware router in front of four 1-GPU SGLang engines."
    serve_vim_dgd
    serve_services
    serve_deploy "$title"
}

# ---- beats/05_slime.sh ----
# beats/05_slime.sh: Step 4, set up the training side with Slime: the ReTool task code.
#
# Data: build/05_slime.data.sh (fill/05_slime.py): a view of functions/generate_with_retool.py (real
# lines with their real numbers, the skipped parts as closed vim folds), the sandbox limits, the
# reward's numbers, and the ConfigMap's apply output.
#
# The code appears in a read-only vim view of the existing file (slime_view_*), not typed with
# vim_open: ReTool's example ships this file, and the point of this beat is that nobody running the
# example writes it. The view reuses the vim emulator's layout (VIM_ROWS, VIM_STL, VIM_TW, VIM_GUT),
# its colors (LNR, MARK, FOLDC, EOB, STL), its callout box (_vim_box, _wrap), and its key timings, so it
# looks like the other vim scenes. Unlike vim_callout, a callout here marks a set of lines, by their
# real line numbers. The view's state lives in locals of slime_code, which its helpers share.

# slime_at ROW: move to column 1 of screen ROW and clear the row.
slime_at() { local e=$'\x1b'; printf '%s[%d;1H%s[K' "$e" "$1" "$e"; }

# Highlight every shown line once, in file order (hl_python carries brackets across lines).
slime_view_hl() {
    local k j h n=${#SLIME_VV_KIND[@]}
    slime_vh=()
    hl_reset python
    for (( k=0; k<n; k++ )); do
        h=""
        if [[ "${SLIME_VV_KIND[k]}" == L ]]; then
            hl_line python "${SLIME_VV_TXT[k]}"
            for (( j=0; j<${#SEG_TXT[@]}; j++ )); do h+="${SEG_COL[j]}${SEG_TXT[j]}"; done
        fi
        slime_vh[k]="$h"
    done
    return 0
}

# slime_view_row ROW K: draw view row K on screen ROW: sign and number columns, then the code or the
# closed fold (vim's foldtext, then '-' to the edge). Past the last row: vim's ~.
slime_view_row() {
    local row=$1 k=$2 num g txt
    slime_at "$row"
    if (( k >= ${#SLIME_VV_KIND[@]} )); then
        printf '%s~%s' "$EOB" "$NC"
        return 0
    fi
    num=${SLIME_VV_NUM[k]}
    printf -v g '%3d ' "$num"
    if [[ "${SLIME_VV_KIND[k]}" == L && "$slime_vmark" == *" ${num} "* ]]; then
        g="${MARK}▶ ${g}${NC}"
    else
        g="  ${LNR}${g}${NC}"
    fi
    if [[ "${SLIME_VV_KIND[k]}" == F ]]; then
        txt="${SLIME_VV_TXT[k]} "
        if (( ${#txt} > VIM_TW )); then txt="${txt:0:VIM_TW}"; fi
        _rep '-' $(( VIM_TW - ${#txt} ))
        printf '%s%s%s%s%s' "$g" "$FOLDC" "$txt" "$_REP" "$NC"
    else
        printf '%s%s%s' "$g" "${slime_vh[k]}" "$NC"
    fi
    return 0
}

# The status line: the file name, then vim's ruler (the cursor's line,col and the view's position).
slime_view_status() {
    local e=$'\x1b' n=${#SLIME_VV_KIND[@]} bot above below rp lc fill left w=$(( COLS - 18 ))
    bot=$(( slime_vtop + VIM_ROWS - 1 ))
    if (( bot >= n )); then bot=$(( n - 1 )); fi
    above=$(( ${SLIME_VV_NUM[slime_vtop]} - 1 ))
    below=$(( SLIME_GEN_NLINES - ${SLIME_VV_LAST[bot]} ))
    if (( below <= 0 )); then
        rp=Bot
    elif (( above <= 0 )); then
        rp=Top
    else
        printf -v rp '%2d%%' $(( above * 100 / (above + below) ))
    fi
    if (( slime_vcol == 0 )); then lc="${slime_vcur},0-1"; else lc="${slime_vcur},${slime_vcol}"; fi
    fill=$(( 18 - ${#lc} - ${#rp} ))
    if (( fill < 1 )); then fill=1; fi
    printf -v left "%-${w}s" "$SLIME_GEN_FILE"
    printf '%s[%d;1H%s%s%s%*s%s%s' "$e" "$VIM_STL" "$STL" "$left" "$lc" "$fill" '' "$rp" "$NC"
}

# Put the terminal cursor on the cursor line's first non-blank character.
slime_view_cursor() {
    local e=$'\x1b' k c
    for (( k=slime_vtop; k<slime_vtop+VIM_ROWS && k<${#SLIME_VV_KIND[@]}; k++ )); do
        if [[ "${SLIME_VV_KIND[k]}" == L ]] && (( ${SLIME_VV_NUM[k]} == slime_vcur )); then
            c=$slime_vcol
            if (( c < 1 )); then c=1; fi
            printf '%s[%d;%dH' "$e" $(( k - slime_vtop + 1 )) $(( VIM_GUT + c ))
            return 0
        fi
    done
    return 0
}

slime_view_draw() {
    local r
    for (( r=1; r<=VIM_ROWS; r++ )); do slime_view_row "$r" $(( slime_vtop + r - 1 )); done
    slime_view_status
}

# slime_view_scroll TOP: scroll down to view row TOP one row at a time, as CTRL-E does. The text rows
# are the terminal's scroll region (set when the view opens), so each step is one newline and one row.
slime_view_scroll() {
    local target=$1 e=$'\x1b' tick="${SLIME_SCROLL_TICK:-0.03}" k
    cursor_hide
    _vim_cmdline ""   # the "FILE" NL, NB message goes once the view moves
    while (( slime_vtop < target )); do
        slime_vtop=$(( slime_vtop + 1 ))
        printf '%s[%d;1H\n' "$e" "$VIM_ROWS"
        slime_view_row "$VIM_ROWS" $(( slime_vtop + VIM_ROWS - 1 ))
        # vim keeps the cursor on screen: when its line scrolls off the top, it moves to the top line.
        for (( k=0; k<slime_vtop; k++ )); do
            if [[ "${SLIME_VV_KIND[k]}" == L ]] && (( ${SLIME_VV_NUM[k]} == slime_vcur )); then
                slime_vcur=${SLIME_VV_NUM[slime_vtop]}; slime_vcol=${SLIME_VV_COL[slime_vtop]}
                break
            fi
        done
        slime_view_status
        nap "$tick"
    done
    return 0
}

# slime_view_scroll_to LINE: scroll down until real line LINE is the top row.
slime_view_scroll_to() {
    local k
    for (( k=0; k<${#SLIME_VV_KIND[@]}; k++ )); do
        if (( ${SLIME_VV_NUM[k]} == $1 )); then slime_view_scroll "$k"; return 0; fi
    done
    die "slime_view_scroll_to: line $1 isn't in the view"
}

# slime_label "N N ..." → slime_lbl: the box label, "▶ line 495" or "▶ lines 403, 420–421".
slime_label() {
    local n a=-1 b=-1 out="" count=0
    for n in $1 -1; do
        if (( a >= 0 && n != b + 1 )); then
            if (( a == b )); then out+="${out:+, }${a}"; else out+="${out:+, }${a}–${b}"; fi
            a=-1
        fi
        if (( n < 0 )); then break; fi
        count=$(( count + 1 ))
        if (( a < 0 )); then a=$n; fi
        b=$n
    done
    if (( count == 1 )); then slime_lbl="▶ line ${out}"; else slime_lbl="▶ lines ${out}"; fi
}

# slime_view_callout "N N ..." PARAGRAPH...: like vim_callout, for real line numbers: mark the lines
# with ▶ and bold numbers, scroll down if needed so they sit above the box (the last one just above
# it, as vim_callout places them), show the box for its reading time, then remove it.
slime_view_callout() {
    local marks="$1" p h avail first=-1 last=-1 k n=${#SLIME_VV_KIND[@]}
    shift
    local -a lines=()
    for p in "$@"; do _wrap $(( COLS - 4 )) "$p"; lines+=("${_WL[@]}"); done
    h=$(( ${#lines[@]} + 2 ))
    avail=$(( VIM_ROWS - h ))
    for (( k=0; k<n; k++ )); do
        if [[ "${SLIME_VV_KIND[k]}" == L && " ${marks} " == *" ${SLIME_VV_NUM[k]} "* ]]; then
            if (( first < 0 )); then first=$k; fi
            last=$k
        fi
    done
    if (( first < 0 )); then die "slime_view_callout: none of lines ${marks} is in the view"; fi
    if (( last - slime_vtop + 1 > avail )); then slime_view_scroll $(( last - avail + 1 )); fi
    if (( first < slime_vtop )); then die "slime_view_callout: lines ${marks} don't fit above a ${h}-row box"; fi
    slime_label "$marks"
    slime_vcur=${SLIME_VV_NUM[first]}; slime_vcol=${SLIME_VV_COL[first]}
    cursor_hide
    nap "$CALLOUT_LEAD"
    slime_vmark=" ${marks} "
    slime_view_draw
    _vim_box "$h" "$slime_lbl" "${lines[@]}"
    read_hold_at "$CALLOUT_WPM" "$CALLOUT_FLOOR" "$@"
    slime_vmark=""
    slime_view_draw
    slime_view_cursor
    cursor_show
}

# slime_view_open LINE: type "vim +LINE FILE", then show the file from LINE with vim's "FILE" NL, NB.
slime_view_open() {
    local line=$1 e=$'\x1b' k n=${#SLIME_VV_KIND[@]}
    show_command "vim +${line} ${SLIME_GEN_FILE}"
    slime_view_hl
    slime_vtop=-1
    for (( k=0; k<n; k++ )); do
        if (( ${SLIME_VV_NUM[k]} == line )); then slime_vtop=$k; break; fi
    done
    if (( slime_vtop < 0 )); then die "slime_view_open: line ${line} isn't in the view"; fi
    slime_vcur=$line; slime_vcol=${SLIME_VV_COL[slime_vtop]}
    VIM_ACTIVE=1   # so the runner leaves the alternate screen if the demo stops inside the view
    cursor_hide
    printf '%s[?1049h%s[H%s[2J%s[1;%dr' "$e" "$e" "$e" "$e" "$VIM_ROWS"
    slime_view_draw
    _vim_cmdline "\"${SLIME_GEN_FILE}\" ${SLIME_GEN_NLINES}L, ${SLIME_GEN_NBYTES}B"
    slime_view_cursor
    cursor_show
    nap "$VIM_OPEN_HOLD"
}

# slime_view_close: type :q (nothing changed, so vim exits without a message) and go back to the shell.
slime_view_close() {
    local e=$'\x1b' cmd=":q" k
    nap "$VIM_KEY_PAUSE"
    _vim_cmdline ""
    for (( k=0; k<${#cmd}; k++ )); do
        printf '%s' "${cmd:k:1}"
        nap "$VIM_KEY_CHAR"
    done
    nap "$VIM_KEY_PAUSE"
    printf '%s[r%s[?1049l' "$e" "$e"
    VIM_ACTIVE=0
    cursor_show
}

# The code, part by part: generate's turn loop, then reward_func.
slime_code() {
    local -a slime_vh=()
    local slime_vtop=0 slime_vmark="" slime_vcur=0 slime_vcol=1 slime_lbl=""
    slime_view_open "$SLIME_GEN_LN"
    slime_view_callout "$SLIME_MARK_C1" \
        "Slime calls ${FUNC}generate${NC} once per trajectory. Every turn goes to the Dynamo frontend (DYNAMO_ROLLOUT_URL)."
    slime_view_callout "$SLIME_MARK_C2" \
        "The turn loop: up to ${NUM}${BOLD}${SLIME_MAX_TURNS}${NC} turns. Each sends the whole transcript so far as token IDs, with logprobs for training."
    slime_view_callout "$SLIME_MARK_C3" \
        "One streaming request through Dynamo. The model writes until it calls the tool (stopping at ${SLIME_STOP}) or answers."
    slime_view_callout "$SLIME_MARK_C4" \
        "Append the reply. ${BOLD}trainable=True${NC}: training learns from these tokens."
    slime_view_callout "$SLIME_MARK_C5" \
        "${FUNC}execute_predictions${NC} runs the code in the sandbox and wraps its output in <interpreter> tags. An answer ends the loop."
    slime_view_callout "$SLIME_MARK_C6" \
        "Append the sandbox output with ${BOLD}trainable=False${NC}: context for the next turn, not the model's own words."
    slime_view_scroll_to "$SLIME_REWARD_LN"
    slime_view_callout "$SLIME_MARK_R" \
        "${FUNC}reward_func${NC}: ${OK}+1${NC} if the final \boxed{} answer matches the label. Otherwise −1 + ${SLIME_REWARD_STEP} × (tool calls − ${SLIME_REWARD_FREE}), at most ${SLIME_REWARD_CAP}. Slime calls it right after each generate, so scoring is part of the rollout."
    slime_view_close
}

beat_05() {
    local title="Step 4: Set Up the Training Side with Slime"
    beat_header "🧩" "$title"
    narrate "Slime, THUDM's RL training framework, runs the training side. Setting it up takes two pieces:" \
            "the task code (this step), which makes and scores trajectories, and a RayJob (Step 5) whose entrypoint is" \
            "python3 train.py <args>: a declarative ray job submit, as the DGD's engines run python3 -m sglang.launch_server."
    card "Who writes generate?" \
         "Built into Slime: a ${FUNC}generate${NC} that sends one request per trajectory, enough for single-turn tasks." \
         "Multi-turn tool use needs its own. Slime's ReTool example ships one: ${SLIME_EXAMPLE_PATH}." \
         "Your own multi-turn task or tool: write or adapt one. This kit runs a patched copy (PATCH comments): every turn streams through Dynamo, plus bug fixes."
    narrate "The kit's copy, from generate:"
    slime_code
    narrate "Slime imports both functions by name, so they ship as a ConfigMap; Step 5 mounts it on PYTHONPATH:"
    show_command 'kubectl apply -n $NAMESPACE -f manifests/functions.yaml'
    printf '%s\n' "$SLIME_CM_APPLY_OUT"
    nap "$PAUSE_MED"
}

# ---- beats/06_rayjob.sh ----
# beats/06_rayjob.sh: Step 5, launch training on KubeRay: the RayJob, line by line, then its Pods.
#
# Data: build/06_rayjob.data.sh (fill/06_rayjob.py): manifests/rayjob.yaml without its kit-internal
# header comment, split where the beat pauses (RAYJOB_Y_*), the buffer lines each callout marks
# (RAYJOB_E*_FROM/TO), the numbers the callouts quote, the apply output (runs/run1.console.log), and
# the head and submitter Pods (runs/run1/pods-watch.txt, the first snapshot with both ready). The
# submitter's own log (`kubectl logs job/slime-retool`) is left to beat 08, which follows it.

rayjob_manifest() {
    narrate "Write the RayJob: KubeRay starts a Ray cluster, submits the entrypoint, and deletes the cluster when the job ends:"
    vim_open "$RAYJOB_FILE"
    vim_type normal "${RAYJOB_Y_HEAD[@]}"
    vim_callout "$RAYJOB_E1_FROM" "$RAYJOB_E1_TO" \
        "${BOLD}train.py${NC}, Slime's entry point, starts the trainer and the rollout manager as Ray actors and runs the loop. The rest are its flags."
    vim_type fast "${RAYJOB_Y_ENGINES[@]}"
    vim_callout "$RAYJOB_E2_FROM" "$RAYJOB_E2_TO" \
        "Use Step 3's ${RAYJOB_ENGINES} engine Services instead of launching engines. Weight sync by disk: the trainer writes each new version to /data/weight-updates, and the engines load it."
    vim_collapse "Qwen3-4B's shape and checkpoints, for Megatron-LM" "${RAYJOB_Y_MODEL[@]}"
    vim_callout "$RAYJOB_E3_FROM" "$RAYJOB_E3_TO" \
        "${BOLD}Megatron-LM${NC}: NVIDIA's library for training transformers across many GPUs, Slime's training backend."
    vim_type fast "${RAYJOB_Y_DATA[@]}"
    vim_callout "$RAYJOB_E4_FROM" "$RAYJOB_E4_TO" \
        "A ${BOLD}step${NC}: one rollout, one training update, one weight sync (${NUM}${BOLD}${RAYJOB_STEPS}${NC} here). A rollout: ${NUM}${BOLD}${RAYJOB_PROBLEMS} problems × ${RAYJOB_SAMPLES} trajectories${NC} (Slime calls each a ${BOLD}sample${NC}); a problem's ${RAYJOB_SAMPLES} are a ${BOLD}group${NC}, siblings. Global batch ${RAYJOB_GBS}: all ${RAYJOB_PER_STEP} make one optimizer update."
    vim_collapse "the optimizer (Adam), its state offloaded to CPU memory" "${RAYJOB_Y_OPTIM[@]}"
    vim_type fast "${RAYJOB_Y_GRPO[@]}"
    vim_callout "$RAYJOB_E5_FROM" "$RAYJOB_E5_TO" \
        "${BOLD}GRPO${NC} is just an algorithm for turning rewards into weight updates (Slime also has ${RAYJOB_OTHER_ALGOS}). It scores each trajectory against its group's mean and spread; above-average ones become more likely. No critic model needed."
    vim_type fast "${RAYJOB_Y_PARALLEL[@]}"
    vim_callout "$RAYJOB_E6_FROM" "$RAYJOB_E6_TO" \
        "${BOLD}TP ${RAYJOB_TP}${NC}: each layer's weight matrices are split across ${RAYJOB_TP} GPUs. ${BOLD}CP ${RAYJOB_CP}${NC}: each trajectory's tokens are split across ${RAYJOB_CP} GPUs, for up to ${RAYJOB_MAXCTX} tokens. Together, ${RAYJOB_GPUS} GPUs per model copy."
    vim_type fast "${RAYJOB_Y_FUNCS[@]}"
    vim_callout "$RAYJOB_E7_FROM" "$RAYJOB_E7_TO" \
        "Step 4's functions, from the ConfigMap on PYTHONPATH. DYNAMO_ROLLOUT_URL: where generate sends every turn."
    vim_type fast "${RAYJOB_Y_CLUSTER[@]}" "${RAYJOB_Y_VOLUMES[@]}"
    vim_callout "$RAYJOB_E8_FROM" "$RAYJOB_E9_TO" \
        "One head Pod, no workers: ${RAYJOB_GPUS} GPUs for Megatron-LM; ${RAYJOB_CPUS} CPUs and ${RAYJOB_MEM} for the CPU-offloaded optimizer and the sandbox's processes. It mounts /data, Step 2's Azure Managed Lustre volume, and Step 4's ConfigMap at /opt/slime-functions."
    vim_close
}

beat_06() {
    local title="Step 5: Launch Training on KubeRay"
    beat_header "🧠" "$title"
    rayjob_manifest
    narrate "Apply it:"
    show_command 'kubectl apply -n $NAMESPACE -f manifests/rayjob.yaml'
    printf '%s\n' "$RAYJOB_APPLY_OUT"
    nap "$PAUSE_SHORT"
    narrate "KubeRay starts the Ray head Pod, then a submitter Pod that runs ray job submit with the entrypoint:"
    show_command "kubectl get pods -n \$NAMESPACE -l ${RAYJOB_SELECTOR}"
    printf '%s\n' "${RAYJOB_PODS_OUT[@]}"
    nap 3
}

# ---- beats/07_trajectory.sh ----
# Beat 07: a closer look inside a rollout: one trajectory, turn by turn (results agent).
# Data: build/07_trajectory.data.sh (fill/07_trajectory.py): tools/trajectory.py's real output for sample 958,
# and one note per turn whose quotes are checked against the model's own text in runs/run1/turns.joined.jsonl.

TRAJECTORY_TITLE="Inside a Rollout: One Trajectory, Turn by Turn"

# trajectory_note LINE...: a note under one turn of the tool's output, indented, paced like narration.
trajectory_note() {
    local line
    for line in "$@"; do
        nap "$NAR_LEAD"
        printf '%s\n' "${NAR}   # ${line}${NC}"
        read_hold "$NAR_FLOOR" "$line"
    done
}

beat_07() {
    local k i start end n=${#TRAJECTORY_TURN_START[@]}
    beat_header "🔍" "$TRAJECTORY_TITLE" \
        "From step ${TRAJECTORY_STEP}'s rollout (the ${TRAJECTORY_STEP_ORD} of ${TRAJECTORY_NSTEPS}), served on ${TRAJECTORY_VERSION}: the starting weights after ${TRAJECTORY_STEP} training updates"
    narrate "While the job runs, zoom into one rollout: one trajectory (one attempt) of its ${TRAJECTORY_STEP_TRAJ}." \
            "--sample ${TRAJECTORY_SAMPLE} is Slime's index for it: the ${TRAJECTORY_PROBLEM_NTH} of step ${TRAJECTORY_STEP}'s $(( TRAJECTORY_STEP_TRAJ / TRAJECTORY_GROUP_SIZE )) problems, attempt ${TRAJECTORY_ATTEMPT} of ${TRAJECTORY_GROUP_SIZE}." \
            "\"${TRAJECTORY_NCODE} ${TRAJECTORY_NOUT}\": show up to ${TRAJECTORY_NCODE} code lines and ${TRAJECTORY_NOUT} output line per turn."
    printf '\n'
    show_command "$TRAJECTORY_CMD"
    nap "$PAUSE_SHORT"
    printf '%s\n' "$TRAJECTORY_HEAD" "${TRAJECTORY_Q[@]}"
    nap "$PAUSE_LONG"
    for (( k=0; k<n; k++ )); do
        start=${TRAJECTORY_TURN_START[$k]}
        if (( k + 1 < n )); then end=${TRAJECTORY_TURN_START[$((k + 1))]}; else end=${#TRAJECTORY_LINES[@]}; fi
        for (( i=start; i<end; i++ )); do
            printf '%s\n' "${TRAJECTORY_LINES[$i]}"
        done
        nap 0.6
        trajectory_note "${TRAJECTORY_NOTES[$k]}"
    done
    printf '\n'
    narrate_wrap "The model never planned ${TRAJECTORY_NTURNS} turns or saw a limit: it writes until it calls the tool or answers." \
                 "The rollout code stops it at an answer, ${TRAJECTORY_MAX_REQUESTS} requests, or ${TRAJECTORY_TOKEN_CAP} tokens." \
                 "Turns 2–${TRAJECTORY_NTURNS} resent the whole history, and ${TRAJECTORY_ENGINE} still held ${TRAJECTORY_HIT_LO}–${TRAJECTORY_HIT_HI}% of each prompt in its cache." \
                 "All ${TRAJECTORY_GROUP_RIGHT} attempts at this problem were right, so none beat the group's average: GRPO learns nothing from this group."
    nap "$PAUSE_MED"
}

# ---- beats/08_loop.sh ----
# Beat 08: Step 6: run the loop 10 times (results agent).
# Data: build/08_loop.data.sh (fill/08_loop.py): the RayJob's clock (rayjob.yaml), Slime's per-step times and
# correct answers (summary.json, from the driver log), each weight load from the SGLang sidecar's is_pause lines,
# and real `kubectl logs | grep` output for the first weight sync (runs/run1/worker-0.final.log).

LOOP_TITLE="Step 6: Run the Loop 10 Times"
LOOP_SLOW_TICK="${LOOP_SLOW_TICK:-0.08}"    # per frame (4 run-seconds) until step 0's weight sync is done
LOOP_EVENT_TICK="${LOOP_EVENT_TICK:-0.5}"   # after each change before then, so the order of events reads
LOOP_FAST_TICK="${LOOP_FAST_TICK:-0.06}"    # per frame (12 run-seconds) for steps 1-9
LOOP_SLOW_DT=4
LOOP_FAST_DT=12   # few frames: each nap forks sleep, which a loaded machine slows down
LOOP_HEADER=""
LOOP_ROWS=()   # the frame without its status line; rebuilt only when an event passes

loop_milestones() {  # t
    local t="$1"
    if (( t >= LOOP_ENGINES_T )); then
        fl "  ${OK}✓${NC} Slime attached to the 4 Dynamo engines (${LOOP_ENGINE_SVCS})"
    else
        fl "  ${DIM}▸ KubeRay starts the Ray head Pod and submits train.py...${NC}"
    fi
    if (( t >= LOOP_V1_LOAD_T )); then
        fl "  ${OK}✓${NC} Initial weight sync v1: written to Lustre in ${LOOP_V1_WRITE_S} s, loaded by the 4 engines in ${LOOP_V1_LOAD_S} s"
    elif (( t >= LOOP_V1_WRITE_T )); then
        fl "  ${DIM}▸ The 4 engines load v1 from Lustre...${NC}"
    elif (( t >= LOOP_V1_WRITE_FROM_T )); then
        fl "  ${DIM}▸ The trainer writes its starting weights, v1, to Lustre...${NC}"
    elif (( t >= LOOP_ENGINES_T )); then
        fl "  ${DIM}▸ The trainer starts on its 4 GPUs and loads the torch_dist checkpoint...${NC}"
    else
        fl ""
    fi
}

loop_row() {  # step t
    local k="$1" t="$2" c0 c1 c2 c3 v="v$(( $1 + 1 ))" next="v$(( $1 + 2 ))"
    local r_txt r_col="$NC" t_txt="" t_col="$NC" s_txt="" s_col="$NC" a_txt=""
    if (( t < ${LOOP_START_T[$k]} )); then
        fl ""
        return 0
    fi
    if (( t >= ${LOOP_ROLLOUT_T[$k]} )); then
        r_txt="${v}: ${LOOP_ROLL_S[$k]} s, ${LOOP_RPT[$k]} requests per trajectory"
        a_txt="${LOOP_CORRECT[$k]}%"
    else
        r_txt="${v}: rollout running..."; r_col="$DIM"
    fi
    if (( t >= ${LOOP_TRAIN_T[$k]} )); then
        t_txt="${LOOP_TRAIN_S[$k]} s"
    elif (( t >= ${LOOP_ROLLOUT_T[$k]} )); then
        t_txt="training..."; t_col="$DIM"
    fi
    if (( t >= ${LOOP_LOAD_T[$k]} )); then
        s_txt="${next}: write ${LOOP_WRITE_S[$k]} s, load ${LOOP_LOAD_S[$k]} s"; s_col="$OK"
    elif (( t >= ${LOOP_WRITE_T[$k]} )); then
        s_txt="4 engines loading ${next}..."; s_col="$DIM"
    elif (( t >= ${LOOP_TRAIN_T[$k]} )); then
        s_txt="writing ${next} to Lustre..."; s_col="$DIM"
    fi
    padr c0 8 "  $k"
    padr c1 45 "$r_txt"
    padr c2 10 "$t_txt"
    padr c3 35 "$s_txt"
    fl "${c0}${r_col}${c1}${NC}${t_col}${c2}${NC}${s_col}${c3}${NC}${a_txt}"
}

loop_status() {  # t
    local t="$1"
    if (( t >= LOOP_DONE_T )); then
        fmt_age "$LOOP_DONE_T"
        fl "  ${OK}✅ Job '${LOOP_JOB_ID}' succeeded · ${AGE_STR} after the RayJob was created${NC}"
    else
        ff_elapsed "$t"
    fi
}

# loop_frame t changed: the table at run time t. Its rows are rebuilt only when an event has passed.
loop_frame() {
    local t="$1" k
    if (( $2 )); then
        FRAME=()
        loop_milestones "$t"
        fl ""
        fl "${BOLD}${LOOP_HEADER}${NC}"
        for (( k=0; k<10; k++ )); do
            loop_row "$k" "$t"
        done
        fl ""
        LOOP_ROWS=("${FRAME[@]}")
    else
        FRAME=("${LOOP_ROWS[@]}")
    fi
    loop_status "$t"
}

# Play the run on its own clock: 4 s frames with a pause on each change until step 0's sync is done, then 12 s frames.
loop_play() {
    local t=0 ev=0 last=-1 n=${#LOOP_EVENTS[@]} dt tick changed
    printf -v LOOP_HEADER '  %-6s%-45s%-10s%-35s%s' "STEP" "ROLLOUT" "TRAIN" "WEIGHT SYNC" "CORRECT"
    frame_reset
    cursor_hide
    while :; do
        while (( ev < n )) && (( ${LOOP_EVENTS[$ev]} <= t )); do ev=$((ev + 1)); done
        changed=0
        if (( ev != last )); then changed=1; fi
        loop_frame "$t" "$changed"
        frame_draw
        if (( t >= LOOP_DONE_T )); then break; fi
        if (( t < ${LOOP_LOAD_T[0]} )); then
            dt=$LOOP_SLOW_DT; tick=$LOOP_SLOW_TICK
            if (( changed && last >= 0 )); then tick=$LOOP_EVENT_TICK; fi
        else
            dt=$LOOP_FAST_DT; tick=$LOOP_FAST_TICK
        fi
        last=$ev
        nap "$tick"
        t=$(( t + dt ))
        if (( t > LOOP_DONE_T )); then t=$LOOP_DONE_T; fi
    done
    frame_reset
    cursor_show
}

beat_08() {
    local cmd='kubectl logs -n $NAMESPACE -f job/slime-retool' note="   # condensed to one row per step"
    beat_header "🔁" "$LOOP_TITLE"
    narrate "Back to the start: the RayJob runs one weight sync, then 10 steps of rollout → train → weight sync." \
            "The first sync loads the trainer's starting weights into the engines as v1 (weight version 1). In worker-0's log:"
    printf '\n'
    show_command_lines "${LOOP_LOG_CMD[@]}"
    printf '%s\n' "${LOOP_LOG_OUT[@]}"
    nap "$PAUSE_LONG"
    printf '\n'
    narrate "Slime decides when, not Dynamo. It tells each engine to pause, flush its KV cache, load the weights, and resume." \
            "All 4 engines do it together, in place, between rollouts (no requests in flight): no restart, no rolling update."
    narrate "Now all 10 steps, one row each:"
    printf '\n'
    show_command "$cmd" "$note"

    clear_screen
    step_header_bars "🔁" "$LOOP_TITLE"
    print_command "$cmd" "$note"
    printf '\n'
    local -a legend=(
        "Dynamo serves every turn of the step's 256 trajectories on vN, and reward_func scores each one."
        "No model loading here. It ends with the slowest trajectory. Requests per trajectory: turns, averaged."
        "The job from Steps 4–5 at work: Megatron-LM turns the 256 scored trajectories into one GRPO update."
        "The trainer writes vN+1 to Lustre (write); the 4 engines pause, load it, and resume (load)."
    )
    printf '%s\n' "  ${BOLD}ROLLOUT${NC}      ${NAR}${legend[0]}${NC}" \
                  "               ${NAR}${legend[1]}${NC}" \
                  "  ${BOLD}TRAIN${NC}        ${NAR}${legend[2]}${NC}" \
                  "  ${BOLD}WEIGHT SYNC${NC}  ${NAR}${legend[3]}${NC}"
    printf '\n'
    # The legend stays up while the table plays: hold for half its reading time first.
    read_hold_at $(( NAR_WPM * 2 )) "$PAUSE_LONG" "${legend[@]}"
    loop_play
    printf '\n'
    narrate "CORRECT ran ${LOOP_CORRECT_MIN}–${LOOP_CORRECT_MAX}% with no trend: each step drew new problems, and 10 steps are too few (upstream runs ${LOOP_UPSTREAM_STEPS})." \
            "What it does confirm: the engines served the trainer's weights (their token log-probabilities matched to about ${LOOP_LOGPROB_GAP})."
    nap "$PAUSE_MED"
}

# ---- beats/09_compare.sh ----
# Beat 09: did KV-aware routing help? KV-aware vs round-robin (results agent; charts since 2026-11-19).
# Data: build/09_compare.data.sh (fill/09_compare.py): real `diff` output, the example hit from sample 958's turn 2,
# run1's routing view (summary.json), and the real output of tools/compare_bars.py, which charts
# runs/compare-kv-rr.json in three screens: what KV-aware routing changed in the engines, whether the run got
# faster, and where each step's slowest trajectory spent its time.

COMPARE_TITLE="Did KV-Aware Routing Help? KV-Aware vs Round-Robin"

# compare_screen NARRATION CMD HOLD LINE...: a clean screen under the pinned header, one narration line, the
# command, its output (LINE...), and HOLD seconds to read the charts. A chart screen is at most 31 rows tall
# (fill/09_compare.py checks the charts' rows), so the header stays on the top row.
compare_screen() {
    local nar="$1" cmd="$2" hold_s="$3"
    shift 3
    clear_screen
    step_header_bars "📊" "$COMPARE_TITLE"
    narrate "$nar"
    show_command "$cmd"
    printf '%s\n' "$@"
    nap "$hold_s"
}

beat_09() {
    beat_header "📊" "$COMPARE_TITLE" \
        "What KV-aware routing saved, and whether that made the run faster than a round-robin baseline."
    card "Prefix cache, hits, and turns that stay" \
        "Each engine keeps a ${BOLD}prefix cache${NC}: the KV cache (attention keys and values) of requests it served. A new prompt that starts with the same tokens reuses them instead of recomputing them (prefill)." \
        "A ${BOLD}hit${NC}: sample ${COMPARE_HIT_SAMPLE}'s turn 2 sent ${COMPARE_HIT_PROMPT} prompt tokens and found ${COMPARE_HIT_CACHED} (${COMPARE_HIT_PCT}%) on worker-0. It computed only ${COMPARE_HIT_COMPUTED}: the sandbox output and a part-filled ${COMPARE_BLOCK}-token block. ${BOLD}Hit rate${NC}: cached ÷ all prompt tokens." \
        "A follow-up turn ${BOLD}stayed${NC} if it went to its previous turn's engine. With KV routing ${COMPARE_STAYED_KV}% stayed and ${COMPARE_MOVED_KV}% moved: the router also weighs load; engines' load gaps often exceeded a turn's history (median ${COMPARE_LOAD_SPREAD} vs ${COMPARE_HISTORY} blocks)."
    narrate "The baseline reran the same RayJob on the same node, engines, and problems. Only the router changed:"
    show_command "$COMPARE_DIFF_CMD"
    printf '%s\n' "${COMPARE_DIFF_OUT[@]}"
    nap "$PAUSE_MED"

    compare_screen "First, the work: what KV-aware routing changed inside the engines, over all ${COMPARE_STEPS} steps." \
        "$COMPARE_WORK_CMD" 9 "${COMPARE_WORK_OUT[@]}"
    compare_screen "Then the time: did that make the run any faster?" \
        "$COMPARE_TIME_CMD" 8 "${COMPARE_TIME_OUT[@]}"
    compare_screen "Why not? Each rollout waits for its slowest trajectory. Where those ${COMPARE_STEPS} spent their time:" \
        "$COMPARE_SLOWEST_CMD" 1 "${COMPARE_SLOWEST_OUT[@]}"
    printf '\n'
    narrate "Verdict: KV-aware routing nearly halved the prefill, not the run time. The run is decode-bound:" \
            "its slowest trajectories mostly generate tokens, and a cache hit only saves prefill." \
            "Step-to-step swings came from long replies and ${COMPARE_TIMEOUT_S} s sandbox timeouts (${COMPARE_TIMEOUTS_RR} in round-robin's, ${COMPARE_TIMEOUTS_KV} in KV-aware's)." \
            "Caveats: one run per router, and both used page size 16, which KV routing needs" \
            "(about ${COMPARE_PAGE16_PCT}% slower decode than the default, in an earlier test on a smaller model)."
    nap "$PAUSE_LONG"
}

# ---- beats/10_closing.sh ----
# Beat 10: closing card (results agent). Data: build/10_closing.data.sh (fill/10_closing.py): the run's node
# and GPUs, its totals (summary.json, compare-kv-rr.json), and the weight syncs' write and load times.

CLOSING_TITLE="Done: Slime Trained Qwen3-4B for 10 Steps, and Dynamo Served Every Turn"
CLOSING_HOLD="${CLOSING_HOLD:-12}"   # seconds on the final card

closing_row() {  # label text
    local c
    padr c 13 "$1"
    printf '%s\n' "   ${BOLD}${c}${NC}${2}"
}

beat_10() {
    beat_header "🎉" "$CLOSING_TITLE"   # the last frame of the recording: the card alone
    closing_row "Hardware" "One ${CLOSING_INSTANCE} node on AKS: ${CLOSING_ENGINE_GPUS} GPUs for Dynamo's SGLang engines, ${CLOSING_TRAINER_GPUS} for Slime's trainer"
    closing_row "Storage" "Azure Managed Lustre: the model, the dataset, and ${CLOSING_SYNCS} weight syncs"
    closing_row "Work" "${CLOSING_TRAJ} trajectories, ${CLOSING_REQ} requests (${CLOSING_RPT} per trajectory), ${CLOSING_OUT_TOKENS} tokens generated"
    closing_row "Time" "RayJob ${CLOSING_RAYJOB}: rollouts ${CLOSING_ROLLOUT_S} s, training ${CLOSING_TRAIN_S} s, weight syncs ${CLOSING_SYNC_S} s (write ${CLOSING_WRITE_S} s + load ${CLOSING_LOAD_S} s)"
    closing_row "Answers" "${CLOSING_RIGHT} of ${CLOSING_TRAJ} correct (${CLOSING_RIGHT_PCT}%). Ten steps are too few to show learning."
    closing_row "KV routing" "Prefill work nearly halved (${CLOSING_PREFILL_KV} vs ${CLOSING_PREFILL_RR} tokens), with no measurable speedup here."
    printf '\n'
    printf '%s\n' "   ${PROMPT}${BOLD}Slime trains. Dynamo serves every turn. New weights every step. 🔁${NC}"
    printf '\n'
    hold "$CLOSING_HOLD"
}

